//! Rust SDK emitter — OpenSDK IR → generated Rust SDK code (Rust port of
//! `@xyd-js/opensdk-rust`, S6+ W7). Emits the FULL generated file tree: Cargo.toml,
//! src/lib.rs, src/client.rs, src/models.rs, one src/<resource>.rs per top-level
//! resource, the vendored reqwest/tokio runtime (src/error.rs + src/transport.rs),
//! and the SDK's own `#[tokio::test]` suite (tests/common/mod.rs + tests/<resource>.rs).
//!
//! Faithful to the framework orchestrator capability order (project → client →
//! types → resources → runtime → tests): the `// Code generated by opensdk. DO NOT
//! EDIT.` ownership header is prepended (+ one blank line) to every `.rs` file, and
//! NOT to Cargo.toml (unknown extension). The vendored runtime is a fixed reqwest/
//! tokio source with `__XYD_*__` seams substituted from `sdkBehavior(spec)`; the
//! test suite's example values come from the shared language-neutral planner.
//!
//! CLI mode: a spec with a root `x-cli` block (see `xyd_opensdk_cli_common`)
//! instead produces an SDK that spawns the real CLI binary — see `cli.rs`.

mod cli;
mod client;
mod example;
mod example_plan;
mod model;
mod naming;
mod plan;
mod project;
mod rstype;
mod rswriter;
mod runtime;
mod service;
mod tests_gen;

use serde_json::{Map, Value};
use std::collections::BTreeMap;

use naming::{crate_name, screaming_snake_case, snake_case};

/// Prepend the ownership header for `.rs` files (as `// ...`), exactly once.
/// `.toml` (Cargo.toml) gets no header — matching the orchestrator's
/// extension table.
// The header text + per-extension comment table live in xyd_opensdk_core. The
// shared table is wider than this crate's old gate, but provably output-neutral:
// the only other extension in these goldens is one the table does not cover.
fn with_header(rel_path: &str, content: String) -> String {
    xyd_opensdk_core::header::with_file_header(rel_path, content)
}

/// The Cargo package / lib crate name (packageName ?? moduleName ?? crateName).
fn resolve_crate(spec: &Value) -> String {
    // Options are folded into the IR call in the JS; the Rust entry takes only
    // the spec (the emitter tests pass no options), so use the defaults.
    let title = spec
        .get("info")
        .and_then(|i| i.get("title"))
        .and_then(|t| t.as_str())
        .unwrap_or("");
    crate_name(title)
}

fn resolve_env_var(spec: &Value, crate_: &str) -> String {
    spec.get("security")
        .and_then(|s| s.as_array())
        .and_then(|arr| {
            arr.iter().find_map(|s| {
                s.get("envVar")
                    .and_then(|e| e.as_str())
                    .filter(|e| !e.is_empty())
            })
        })
        .map(|e| e.to_string())
        .unwrap_or_else(|| format!("{}_API_KEY", screaming_snake_case(crate_)))
}

/// Generate the SUBSTANTIVE Rust SDK files from an OpenSDK IR document.
/// Returns `{ relativePath: contents }` for the emitted (generated-code) files.
pub fn generate_rust(spec: &Value) -> BTreeMap<String, String> {
    if xyd_opensdk_cli_common::is_cli_spec(spec) {
        return cli::generate_cli(spec);
    }
    let crate_ = resolve_crate(spec);
    let edition = "2021";
    let env_var = resolve_env_var(spec, &crate_);
    let base_url = spec
        .get("servers")
        .and_then(|s| s.as_array())
        .and_then(|a| a.first())
        .and_then(|s| s.as_str())
        .unwrap_or("")
        .to_string();

    // Symbol table for the resource emitter (name → NamedType).
    let mut types: Map<String, Value> = Map::new();
    if let Some(arr) = spec.get("types").and_then(|t| t.as_array()) {
        for t in arr {
            if let Some(name) = t.get("name").and_then(|n| n.as_str()) {
                types.insert(name.to_string(), t.clone());
            }
        }
    }

    let mut files: BTreeMap<String, String> = BTreeMap::new();
    let mut put = |path: &str, content: String| {
        files.insert(path.to_string(), with_header(path, content));
    };

    // generateProject
    put(
        "Cargo.toml",
        project::render_cargo_toml(spec, &crate_, edition),
    );
    put("src/lib.rs", project::render_lib_rs(spec));
    // generateClient
    put("src/client.rs", client::render_client_file(spec, &env_var));
    // generateTypes
    put("src/models.rs", model::render_models_file(spec));
    // generateResources
    let ctx = service::RustCtx { types: &types };
    if let Some(resources) = spec.get("resources").and_then(|r| r.as_array()) {
        for resource in resources {
            let (path, content) = service::render_service_file(resource, &ctx);
            files.insert(path.clone(), with_header(&path, content));
        }
    }

    // generateRuntime — the vendored reqwest/tokio transport + typed errors,
    // constants driven by sdkBehavior(spec).
    files.insert(
        "src/error.rs".to_string(),
        with_header("src/error.rs", runtime::render_error_file(spec)),
    );
    files.insert(
        "src/transport.rs".to_string(),
        with_header(
            "src/transport.rs",
            runtime::render_transport_file(spec, &crate_, &base_url),
        ),
    );

    // generateTests — the SDK's own #[tokio::test] suite (skipped when there are no
    // resources, matching the JS emitter).
    if let Some(resources) = spec
        .get("resources")
        .and_then(|r| r.as_array())
        .filter(|r| !r.is_empty())
    {
        files.insert(
            "tests/common/mod.rs".to_string(),
            with_header("tests/common/mod.rs", tests_gen::common_mod_rs(&crate_)),
        );
        for resource in resources {
            let name = resource.get("name").and_then(|n| n.as_str()).unwrap_or("");
            let path = format!("tests/{}.rs", snake_case(name));
            let content = tests_gen::resource_test_rs(resource, &crate_, &types);
            files.insert(path.clone(), with_header(&path, content));
        }
    }

    files
}

/// This crate as plain data, for a Rust-side dispatcher and the A2 docs surface.
///
/// Additive only: no call site today, and the two docs slots are `None` until A2
/// implements them. See `xyd_opensdk_core::emitter` for why this is a data
/// descriptor rather than a trait.
pub const EMITTER: xyd_opensdk_core::emitter::EmitterFns =
    xyd_opensdk_core::emitter::EmitterFns::new("rust", generate_rust);
